#include <iostream>
#include <fstream>
#include "vector_curve_sampler.h"
int main(int argc,char**argv){if(argc!=2)return 1;static_assert(sizeof(void*)==8);std::ifstream f(argv[1],std::ios::binary);if(!f)return 1;unsigned checks=0,mismatches=0;while(true){uint32_t mode;int32_t tick;std::array<float,3>expected;f.read(reinterpret_cast<char*>(&mode),4);if(f.gcount()==0&&f.eof())break;f.read(reinterpret_cast<char*>(&tick),4);f.read(reinterpret_cast<char*>(expected.data()),12);if(!f||mode>127)return 2;unsigned flags=mode/16;mode%=16;RecoveredVectorCurveSampler s;s.times={0,10000,30000,70000};s.values={{{0,-3.7f,100.3f}},{{1,9.2f,-5.1f}},{{3,-5.1f,9.2f}},{{7,100.3f,-3.7f}}};s.kinds.assign(4,mode*257);s.info.defaultKind=mode*257;s.info.rightEdgeTime=80000;s.info.useEdgeInfo=(flags&1)!=0;s.info.leftActive=(flags&2)!=0;s.info.rightActive=(flags&4)!=0;s.info.disabledEdgeValue={-8,-10,-12};s.info.defaultEdgeZero={2,3,4};s.info.leftValue={-2,-4,-6};s.info.rightValue={8,10,12};auto actual=s.sample(tick);if(std::memcmp(actual.data(),expected.data(),12)){++mismatches;if(mismatches<5)std::cout<<"mode="<<mode<<" tick="<<tick<<'\n';}++checks;}std::cout<<"native_vector_full_x64_checks="<<checks<<" mismatches="<<mismatches<<'\n';return checks==12928&&!mismatches?0:3;}
